  "content": "Seurat Command List Compiled: 2023-10-31 Source: vignettes/essential_commands.Rmd essential_commands.Rmd Standard Seurat workflow pbmc <- NormalizeData(object = pbmc) pbmc <- FindVariableFeatures(object = pbmc) pbmc <- ScaleData(object = pbmc) pbmc <- RunPCA(object = pbmc) pbmc <- FindNeighbors(object = pbmc, dims = 1:30) pbmc <- FindClusters(object = pbmc) pbmc <- RunUMAP(object = pbmc, dims = 1:30) DimPlot(object = pbmc, reduction = \"umap\") SCtransform version pbmc <- SCTransform(object = pbmc) pbmc <- RunPCA(object = pbmc) pbmc <- FindNeighbors(object = pbmc, dims = 1:30) pbmc <- FindClusters(object = pbmc) pbmc <- RunUMAP(object = pbmc, dims = 1:30) DimPlot(object = pbmc, reduction = \"umap\") # note that you can chain multiple commands together with %>% pbmc <- SCTransform(pbmc) %>% RunPCA() %>% FindNeighbors(dims = 1:30) %>% FindClusters() %>% RunUMAP(dims = 1:30) Seurat Object Data Access Cell, feature, and layer names # Get cell and feature names, and total numbers We show multiple ways to get the same output cell names colnames(pbmc) Cells(pbmc) # feature names Features(pbmc) rownames(pbmc) # number of cells/features num_cells <- ncol(pbmc) num_features <- nrow(pbmc) # List of object layers Layers(pbmc) # working with multimodal objects list assays Assays(cbmc) # Assay-specific features (genes/ADT) Features(cbmc[[\"RNA\"]]) Features(cbmc[[\"ADT\"]]) # Variable feature names VariableFeatures(pbmc) # Set variable features VariableFeatures(cbmc) <- var.gene.names # set for a specific assay VariableFeatures(cbmc[[\"ADT\"]]) <- var.gene.names Identity class labels # Setting and retrieving cell identities # Set identity classes to an existing column in meta data Idents(object = pbmc) <- \"seurat_annotations\" # View cell identities, get summary table Idents(pbmc) table(Idents(pbmc)) # Set identity to CD4 T cells for all cells Idents(pbmc) <- \"CD4 T cells\" # Set for a selected group of cells pbmc.cells <- Cells(pbmc) Idents(object = pbmc, cells = pbmc.cells[1:10]) <- \"CD4 T cells\" # Get cell identity classes Idents(object = pbmc) levels(x = pbmc) # Stash cell identity classes in metadata pbmc[[\"old.ident\"]] <- Idents(object = pbmc) pbmc <- StashIdent(object = pbmc, save.name = \"old.ident\") # Rename identity classes pbmc <- RenameIdents(object = pbmc, `CD4 T cells` = \"T Helper cells\") Cell metadata # View metadata data frame, stored in object@meta.data pbmc[[]] # Retrieve specific values from the metadata pbmc$nCount_RNA pbmc[[c(\"percent.mito\", \"nFeature_RNA\")]] # Add metadata, see ?AddMetaData random_group_labels <- sample(x = c(\"g1\", \"g2\"), size = ncol(x = pbmc), replace = TRUE) pbmc$groups <- random_group_labels Expression data (stored as layers in Seurat v5) # Retrieve data in an expression matrix RNA counts matrix pbmc[[\"RNA\"]]$counts # Alternate accessor function with the same result LayerData(pbmc, assay = \"RNA\", layer = \"counts\") # GetAssayData from Seurat v4 is still supported GetAssayData(object = pbmc, assay = \"RNA\", slot = \"counts\") # ADT counts matrix (multimodal object) cbmc[[\"ADT\"]]$counts # Set expression data assume new.data is a new expression matrix pbmc[[\"RNA\"]]$counts <- new.data # Alternate setter function with the same result LayerData(pbmc, assay = \"RNA\", layer = \"counts\") <- new.data # SetAssayData from Seurat v4 is still supported pbmc <- SetAssayData(object = pbmc, slot = \"counts\", new.data = new.data) Dimensional reductions # Get cell embeddings and feature loadings stored on pbmc[['pca']]@cell.embeddings Embeddings(pbmc, reduction = \"pca\") # stored in pbmc[['pca]]@feature.loadings Loadings(pbmc, reduction = \"pca\") # Create custom dimensional reduction loadings matrix is optional new_reduction <- CreateDimReducObject(embeddings = new.embeddings, loadings = new.loadings, key = \"custom_pca\") pbmc[[\"custom_pca\"]] <- new_reduction FetchData # FetchData can access anything from expression matrices, cell embeddings, or metadata Use the previously listed # commands to access entire matrices Use FetchData to access individual/small groups of variables FetchData(object = pbmc, vars = c(\"PC_1\", \"nFeature_RNA\", \"MS4A1\"), layer = \"counts\") Subsetting and merging Subset Seurat objects # Subset Seurat object based on identity class, also see ?SubsetData subset(x = pbmc, idents = \"B\") subset(x = pbmc, idents = c(\"Naive CD4 T\", \"CD8 T\"), invert = TRUE) # Subset on the expression level of a gene/feature subset(x = pbmc, subset = MS4A1 > 2.5) # Subset on a combination of criteria subset(x = pbmc, subset = MS4A1 > 2.5 & PC_1 > 5) subset(x = pbmc, subset = MS4A1 > 2.5, idents = \"B\") # Subset on a value in the object meta data subset(x = pbmc, subset = groups == \"g1\") # Downsample the number of cells per identity class subset(x = pbmc, downsample = 100) Split layers # In Seurat v5, users can now split in object directly into different layers keeps expression data in one object, but # splits multiple samples into layers can proceed directly to integration workflow after splitting layers ifnb[[\"RNA\"]] <- split(\n\n[Content truncated]"
